package vn.edu.ltweb.jwtmvc;
import org.junit.jupiter.api.Test; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc; import org.springframework.boot.test.context.SpringBootTest; import org.springframework.http.MediaType; import org.springframework.test.context.ActiveProfiles; import org.springframework.test.web.servlet.MockMvc; import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*; import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@SpringBootTest @AutoConfigureMockMvc @ActiveProfiles("test") class AuthSecurityIntegrationTest { @Autowired MockMvc mvc;
 @Test void usersMeWithoutBearerTokenReturns401Json() throws Exception {mvc.perform(get("/users/me")).andExpect(status().isUnauthorized()).andExpect(jsonPath("$.status").value(401));}
 @Test void duplicateEmailReturns400Json() throws Exception {String b="{\"fullName\":\"A\",\"email\":\"x@example.com\",\"password\":\"password123\"}";mvc.perform(post("/auth/signup").contentType(MediaType.APPLICATION_JSON).content(b)).andExpect(status().isOk());mvc.perform(post("/auth/signup").contentType(MediaType.APPLICATION_JSON).content(b)).andExpect(status().isBadRequest());}}
